require "rails_helper"
require "json"

# Conformance (formal/INTEGRATION.md, layer 3): formal/fixtures/orphaned_queue_job.json
# is QueueExecution.orphanedAfter over every combination of the five SolidQueue
# execution flags, generated by `lake exe syrus_fixtures orphaned_queue_job`.
# This runs the real WorkEngine::Reconciler#orphaned_queue_job? on the same
# flags. A job is orphaned, and safe to delete and re-enqueue, exactly when it
# carries no execution row at all. The test database has no SolidQueue tables,
# so the snapshot that produces the flags is not part of this check.
RSpec.describe "QueueExecution model conformance" do
  fixture = JSON.parse(Rails.root.join("formal/fixtures/orphaned_queue_job.json").read)
  flags = %w[ready claimed scheduled blocked failed]
  let(:reconciler) { WorkEngine::Reconciler.new(source: "conformance") }

  it "covers every combination of the execution flags" do
    expect(fixture.fetch("cases").size).to eq(2**flags.size)
  end

  fixture.fetch("cases").each do |example|
    set = flags.select { |flag| example.fetch(flag) }

    it "calls a job with #{set.empty? ? 'no execution row' : set.join(' and ')} #{example.fetch('orphaned') ? 'orphaned' : 'not orphaned'}" do
      # The flags are the model's `orphanedAfter`; the grace period is its
      # separate `settled` input, so give the job a timestamp well past it.
      long_ago = 1.day.ago
      snapshot = flags.to_h { |flag| [ flag.to_sym, example.fetch(flag) ] }.merge(created_at: long_ago, updated_at: long_ago)

      expect(reconciler.send(:orphaned_queue_job?, snapshot)).to eq(example.fetch("orphaned"))
    end
  end
end
